-import type {IncomingMessage} from '../../types/messages.js';
+import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
+import type {SessionCursor} from '../../types/sessionStore.js';

 const MAX_CONTENT_LENGTH = 10000;
+const SESSION_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

 interface ValidationSuccess {
   valid: true;
@@ -30,6 +32,8 @@ export function validateMessage(payload: unknown): ValidationResult {
       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
@@ -72,3 +76,38 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const data: ListSessionsMessage = {type: 'list_sessions'};
+
+  if (message.limit !== undefined) {
+    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
+      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+    }
+    data.limit = message.limit;
+  }
+
+  if (message.before !== undefined) {
+    const before = parseCursor(message.before);
+    if (before === undefined) {
+      return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
+    }
+    data.before = before;
+  }
+
+  return {valid: true, data};
+}
+
+function parseCursor(raw: unknown): SessionCursor | undefined {
+  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return undefined;
+  const {updatedAt, sessionId} = raw as Record<string, unknown>;
+  if (!isValidCursorMoment(updatedAt)) return undefined;
+  if (typeof sessionId !== 'string' || !SESSION_ID_PATTERN.test(sessionId)) return undefined;
+  return {updatedAt, sessionId};
+}
+
+function isValidCursorMoment(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt === 'string') return Number.isFinite(Date.parse(updatedAt));
+  if (typeof updatedAt === 'number') return Number.isFinite(new Date(updatedAt).getTime());
+  return false;
+}
