  describe('conversation list requests', () => {
    it('answers list_sessions for the socket user with ISO dates, forwarding limit and before', async () => {
      const calls: Array<{userId: string | number; options: unknown}> = [];
      const summaries: SessionSummary[] = [
        {
          sessionId: 's-new',
          createdAt: new Date('2026-03-01T10:00:00.000Z'),
          updatedAt: new Date('2026-03-01T12:00:00.000Z'),
          entryCount: 4,
        },
      ];
      const store = {
        listFor: async (userId: string | number, options?: unknown) => {
          calls.push({userId, options});
          return summaries;
        },
      } as unknown as SessionStore;
      const ws = fakeSocket();
      const session: ChatSession = {sessionId: 's1', userId: 'u-auth', entries: []};
      const handle = createMessageHandler(orchestratorFor([]), undefined, store);
      const before = {updatedAt: '2026-03-01T13:00:00.000Z', sessionId: 's-cursor'};

      await handle(ws, session, {type: 'list_sessions', limit: 10, before, userId: 'u-spoofed'});

      expect({calls, frames: sentMessages(ws)}).toEqual({
        calls: [{userId: 'u-auth', options: {limit: 10, before}}],
        frames: [
          {
            type: 'session_list',
            sessions: [
              {
                sessionId: 's-new',
                createdAt: '2026-03-01T10:00:00.000Z',
                updatedAt: '2026-03-01T12:00:00.000Z',
                entryCount: 4,
              },
            ],
          },
        ],
      });
    });

    it('answers an empty session_list when no store or no listFor is provided, and SERVER_ERROR with a ws error log when listFor throws', async () => {
      const errorLines: unknown[][] = [];
      const nop = (): void => undefined;
      setLogger({debug: nop, info: nop, warn: nop, error: (...args: unknown[]) => void errorLines.push(args)} as Logger);

      const session: ChatSession = {sessionId: 's1', userId: 'u-auth', entries: []};
      const wsNoStore = fakeSocket();
      const wsNoListFor = fakeSocket();
      const wsThrowing = fakeSocket();
      const storeWithoutListFor = {} as unknown as SessionStore;
      const throwingStore = {
        listFor: async () => {
          throw new Error('mongo unreachable');
        },
      } as unknown as SessionStore;

      try {
        await createMessageHandler(orchestratorFor([]))(wsNoStore, session, {type: 'list_sessions'});
        await createMessageHandler(orchestratorFor([]), undefined, storeWithoutListFor)(wsNoListFor, session, {
          type: 'list_sessions',
        });
        await createMessageHandler(orchestratorFor([]), undefined, throwingStore)(wsThrowing, session, {
          type: 'list_sessions',
        });
      } finally {
        setLogger();
      }

      expect({
        noStore: sentMessages(wsNoStore),
        noListFor: sentMessages(wsNoListFor),
        throwing: sentMessages(wsThrowing),
        errorLines,
      }).toEqual({
        noStore: [{type: 'session_list', sessions: []}],
        noListFor: [{type: 'session_list', sessions: []}],
        throwing: [{type: 'error', code: 'SERVER_ERROR', message: 'An error occurred processing your message'}],
        errorLines: [['ws', expect.any(String), expect.objectContaining({userId: 'u-auth', error: 'mongo unreachable'})]],
      });
    });
  });
});

